ALTER FUNCTION [graph].[GetXmlSegment]
(
	@xml xml,
	@assetTypeId int,
	@id bigint,
	@level int
)
RETURNS xml
AS
BEGIN
	if @xml is null
	begin
		set @xml = '<path></path>'
	end

	declare @segment xml;  

	set @segment =	(
					select		@level as '@level',
								ROW_NUMBER() over (order by T.ColumnOrder) as '@position',--T.ColumnOrder as '@position',
								@assetTypeId as '@assetTypeId',
								@id as '@assetId',
								FormattedValue as 'data()'
					from		Field F
								inner join FieldType T on T.ID = F.FieldTypeID and T.IsPartOfKey = 1 and F.AssetID = @id
					order by	T.ColumnOrder
					for xml path('segment')
					)

	SET @xml.modify('             
	insert sql:variable("@segment")             
	into (/path)[1]')

	return @xml
END

