alter procedure [graph].[PopulatePathsForAssetType] @assetTypeID int, @assetID bigint = null as begin set nocount on;
if @assetTypeID is null begin RAISERROR ('Required parameter @assetTypeID not supplied or is NULL.', 10, 1); end
declare @class int = 1, @predicateType int = 3, @sql nvarchar(max) = '', @columnSql nvarchar(max) = '', @segmentSql nvarchar(max) = '', @fromSql nvarchar(max) = '', @whereSql nvarchar(max) = '', @matchSql nvarchar(max) = 'a1';
declare @a table(RowID int identity, AssetTypeID int, [Level] int); declare @f table(RowID int, AssetTypeID int, FieldTypeID int, ColumnOrder int, KeyOrder int identity);
select @class = Class from AssetType where ID = @assetTypeID;
if @class = 2 or @class = 6 begin declare @hierarchy table (ID bigint, [Level] int, Segments xml, [Path] nvarchar(2500)); set @predicateType = 4;
with p as ( select A.ID, A.Object, A.ObjectID, cast(null as varchar(50)) as ParentObject, cast(null as int) as ParentObjectID, 1 as [Level], cast(graph.GetXmlSegment(cast(null as xml), @assetTypeID, A.ID, 1) as xml) as Segments, cast(graph.GetPathSegment(A.ID) as nvarchar(2500)) as Segment from Asset A left join [IntersectDetail] I on I.PredicateType = @predicateType and I.Object = A.Object and I.ObjectID = A.ObjectID where A.AssetTypeID = @assetTypeID and I.ID is null union all select A.ID, A.Object, A.ObjectID, p.Object as ParentObject, p.ObjectID as ParentObjectID, p.[Level]+1 as [Level], cast(graph.GetXmlSegment(p.Segments, @assetTypeID, A.ID, p.[Level]+1) as xml) as Segments, cast(p.Segment+'.'+ graph.GetPathSegment(A.ID) as nvarchar(2500)) as Segment from Asset A inner join [IntersectDetail] I on I.PredicateType = @predicateType and I.Object = A.Object and I.ObjectID = A.ObjectID inner join p on p.Object = I.Subject and p.ObjectID = I.SubjectID where A.AssetTypeID = @assetTypeID and p.[Level] <= 25 ) insert into @hierarchy select ID, [Level], Segments, Segment from p
delete T from @hierarchy T left join ( select ID, max([Level]) as [Level] from @hierarchy group by ID ) S on S.ID = T.ID and S.[Level] = T.[Level] where S.ID is null;
update T set T.[Path] = S.[Path], T.[Segments] = S.[Segments] from graph.AssetNode T inner join @hierarchy S on S.ID = T.ID; end else begin
declare @h table (ID int, [Level] int) insert into @h select ID, [Level] from dbo.GetAssetTypeAncestry(@assetTypeID) order by [Level];
with p2 as ( select A.AssetTypeID, A.ID, A.Object, A.ObjectID, cast(null as varchar(50)) as ParentObject, cast(null as int) as ParentObjectID, 1 as [Level], cast(graph.GetXmlSegment(cast(null as xml), @assetTypeID, A.ID, 1) as xml) as Segments, cast(graph.GetPathSegment(A.ID) as nvarchar(2500)) as Segment from Asset A inner join @h H on H.[Level] = 1 and H.ID = A.AssetTypeID left join PredicateIntersect I on I.PredicateType = @predicateType and I.Object = A.Object and I.ObjectID = A.ObjectID where I.IntersectID is null union all select A.AssetTypeID, A.ID, A.Object, A.ObjectID, p.Object as ParentObject, p.ObjectID as ParentObjectID, p.[Level]+1 as [Level], cast(graph.GetXmlSegment(p.Segments, @assetTypeID, A.ID, p.[Level]+1) as xml) as Segments, cast(p.Segment+'.'+ graph.GetPathSegment(A.ID) as nvarchar(2500)) as Segment from Asset A inner join PredicateIntersect I on I.PredicateType = @predicateType and I.Object = A.Object and I.ObjectID = A.ObjectID inner join p2 as p on p.Object = I.Subject and p.ObjectID = I.SubjectID inner join @h H on H.[Level] = p.[Level]+1 and H.ID = A.AssetTypeID )
update T set T.[Path] = S.Segment, T.[Segments] = S.[Segments] from graph.AssetNode T inner join p2 S on S.AssetTypeID = @assetTypeID and S.ID = T.ID ; end end

changeSet.rollback:
ALTER procedure [graph].[PopulatePathsForAssetType] @assetTypeID int, @assetID bigint = null as begin set nocount on;
if @assetTypeID is null begin RAISERROR ('Required parameter @assetTypeID not supplied or is NULL.', 10, 1); end
declare @class int = 1, @predicateType int = 3, @sql nvarchar(max) = '', @columnSql nvarchar(max) = '', @segmentSql nvarchar(max) = '', @fromSql nvarchar(max) = '', @whereSql nvarchar(max) = '', @matchSql nvarchar(max) = 'a1';
declare @a table(RowID int identity, AssetTypeID int, [Level] int); declare @f table(RowID int, AssetTypeID int, FieldTypeID int, KeyOrder int identity);
select @class = Class from AssetType where ID = @assetTypeID;
if @class = 2 or @class = 6 begin declare @hierarchy table (ID bigint, [Level] int, Segments xml, [Path] nvarchar(2500)); set @predicateType = 4;
with p as ( select A.ID, A.Object, A.ObjectID, cast(null as varchar(50)) as ParentObject, cast(null as int) as ParentObjectID, 1 as [Level], cast(graph.GetXmlSegment(cast(null as xml), @assetTypeID, A.ID, 1) as xml) as Segments, cast(graph.GetPathSegment(A.ID) as nvarchar(2500)) as Segment from Asset A left join [IntersectDetail] I on I.PredicateType = @predicateType and I.Object = A.Object and I.ObjectID = A.ObjectID where A.AssetTypeID = @assetTypeID and I.ID is null union all select A.ID, A.Object, A.ObjectID, p.Object as ParentObject, p.ObjectID as ParentObjectID, p.[Level]+1 as [Level], cast(graph.GetXmlSegment(p.Segments, @assetTypeID, A.ID, p.[Level]+1) as xml) as Segments, cast(p.Segment+'.'+ graph.GetPathSegment(A.ID) as nvarchar(2500)) as Segment from Asset A inner join [IntersectDetail] I on I.PredicateType = @predicateType and I.Object = A.Object and I.ObjectID = A.ObjectID inner join p on p.Object = I.Subject and p.ObjectID = I.SubjectID where A.AssetTypeID = @assetTypeID and p.[Level] <= 25 ) insert into @hierarchy select ID, [Level], Segments, Segment from p
delete T from @hierarchy T left join ( select ID, max([Level]) as [Level] from @hierarchy group by ID ) S on S.ID = T.ID and S.[Level] = T.[Level] where S.ID is null;
update T set T.[Path] = S.[Path], T.[Segments] = S.[Segments] from graph.AssetNode T inner join @hierarchy S on S.ID = T.ID; end else begin with c as ( select T.ID as AssetTypeID, I.SubjectID as ParentID, T.Object, T.ObjectID, 1 as [Level] from AssetType T left join IntersectType I on I.Object = T.Object and I.ObjectID = T.ObjectID and I.PredicateID in (select ID from [Predicate] where Type = @predicateType) where T.ID = @assetTypeID union all select T.ID as AssetTypeID, I.SubjectID as ParentID, T.Object, T.ObjectID, C.[Level] + 1 as [Level] from AssetType T inner join c on T.Object = c.Object and T.ObjectID = c.ParentID outer apply ( select SubjectID from IntersectType where Object = T.Object and ObjectID = T.ObjectID and PredicateID in (select ID from [Predicate] where Type = @predicateType) ) I where c.[Level] < 10 ) insert into @a select AssetTypeID, [Level] from c order by [Level] desc;
insert into @f (RowID, AssetTypeID, FieldTypeID) select A.RowID, A.AssetTypeID, F.ID from @a A inner join FieldType F on F.AssetTypeID = A.AssetTypeID and F.IsPartOfKey = 1 order by A.RowID, F.ColumnOrder, F.Name;
if @class = 4 --Fusion Attribute Type asset class begin select @columnSql = string_agg('''[''+' + 'f'+cast(a.RowID as nvarchar)+'.[Name]' + '+'']''' + coalesce('+''.''+' + f.KeyFields, ''), '+''.''+') from @a A outer apply ( select string_agg('''[''+' + 'f'+cast(RowID as nvarchar)+'k'+cast(KeyOrder as nvarchar)+'.[FormattedValue]' + '+'']''', '+''.''+') as KeyFields from @f where RowID = A.RowID ) f; end if @class = 9 --Reference Item Type asset class begin select @columnSql = string_agg('''[''+' + 'f'+cast(RowID as nvarchar)+'.[Code]' + '+'']''', '+''.''+') from @a; end if @class <> 4 and @class <> 9 --all other asset classes begin select @columnSql = string_agg('''[''+' + 'f'+cast(RowID as nvarchar)+'k'+cast(KeyOrder as nvarchar)+'.[FormattedValue]' + '+'']''', '+''.''+') from @f; end
declare @current int = 1, @max int, @atID int, @sCurrent nvarchar(30) = '' select @max = max(RowID) from @a while @current <= @max begin set @sCurrent = cast(@current as nvarchar(30)) select @atID = AssetTypeID from @a where RowID = @current set @fromSql = @fromSql + iif(@current > 1, ', ', '') + 'graph.AssetNode a'+@sCurrent set @fromSql = @fromSql + iif(@current > 1, ', graph.AssetEdge e'+ @sCurrent, '')
if @class = 4 --Fusion Attribute Type asset class begin select @fromSql = @fromSql + ', ' + string_agg('FusionAttribute f'+@sCurrent+', Asset fa'+@sCurrent, ', ') from @a where RowID = @current select @fromSql = @fromSql + coalesce(', ' + string_agg('FieldDetail f'+@sCurrent+'k'+cast(KeyOrder as nvarchar), ', '), '') from @f where RowID = @current
select @whereSql = @whereSql + string_agg(' and a'+@sCurrent+'.ID = fa'+@sCurrent+'.ID and fa'+@sCurrent+'.Object = ''FusionAttribute'' and fa'+@sCurrent+'.ObjectID = f'+@sCurrent+'.ID', ' ') from @a where RowID = @current select @whereSql = @whereSql + coalesce(string_agg(' and a'+@sCurrent+'.ID = f'+@sCurrent+'k'+cast(KeyOrder as nvarchar)+'.AssetID and f'+@sCurrent+'k'+cast(KeyOrder as nvarchar)+'.FieldTypeID = '+cast(FieldTypeID as nvarchar), ' '), '') from @f where RowID = @current
select @segmentSql = @segmentSql + iif (@segmentSql<>'', ' union ', '') + string_agg('select ' + @sCurrent + ' as [L], ' + cast(@atID as nvarchar) + ' as [A], a' + @sCurrent + '.ID as AssetID, f' + @sCurrent + '.Name as Name',' union ') from @a where RowID = @current --select @segmentSql = @segmentSql + iif (@segmentSql<>'', '+', '') + string_agg('''<segment level="' + @sCurrent+'" assetTypeId="'+cast(@atID as nvarchar)+'" assetId="''+cast(a'+@sCurrent+'.ID as nvarchar)+''"><![CDATA[''+' + 'f'+@sCurrent+'.Name' + '+'']' + ']><' + '/segment>''', '+') from @a where RowID = @current end if @class = 9 --Reference Item Type asset class begin select @fromSql = @fromSql + ', ' + string_agg('Asset f'+@sCurrent, ', ') from @a where RowID = @current select @whereSql = @whereSql + string_agg(' and a'+@sCurrent+'.ID = f'+@sCurrent+'.ID', ' ') from @a where RowID = @current
select @segmentSql = @segmentSql + iif (@segmentSql<>'', ' union ', '') + string_agg('select ' + @sCurrent + ' as [L], ' + cast(@atID as nvarchar) + ' as [A], a' + @sCurrent + '.ID as AssetID, f' + @sCurrent + '.[Code] as Name',' union ') from @a where RowID = @current
--select @segmentSql = @segmentSql + iif (@segmentSql<>'', '+', '') + string_agg('''<segment level="' + @sCurrent+'" assetTypeId="'+cast(@atID as nvarchar)+'" assetId="''+cast(a'+@sCurrent+'.ID as nvarchar)+''"><![CDATA[''+' + 'f'+@sCurrent+'.[Code]' + '+'']' + ']><' + '/segment>''', '+') from @a where RowID = @current end if @class <> 4 and @class <> 9 --all other asset classes begin select @fromSql = @fromSql + ', ' + string_agg('FieldDetail f'+@sCurrent+'k'+cast(KeyOrder as nvarchar), ', ') from @f where RowID = @current select @whereSql = @whereSql + string_agg(' and a'+@sCurrent+'.ID = f'+@sCurrent+'k'+cast(KeyOrder as nvarchar)+'.AssetID and f'+@sCurrent+'k'+cast(KeyOrder as nvarchar)+'.FieldTypeID = '+cast(FieldTypeID as nvarchar), ' ') from @f where RowID = @current
select @segmentSql = @segmentSql + iif (@segmentSql<>'', ' union ', '') + string_agg('select ' + @sCurrent + ' as [L], ' + cast(@atID as nvarchar) + ' as [A], a' + @sCurrent + '.ID as AssetID, f'+@sCurrent+'k'+cast(KeyOrder as nvarchar)+'.FormattedValue as Name',' union ') from @f where RowID = @current --select @segmentSql = @segmentSql + iif (@segmentSql<>'', '+', '') + string_agg('''<segment level="' + @sCurrent+'" assetTypeId="'+cast(@atID as nvarchar)+'" assetId="''+cast(a'+@sCurrent+'.ID as nvarchar)+''"><![CDATA[''+' + 'f'+@sCurrent+'k'+cast(KeyOrder as nvarchar)+'.FormattedValue' + '+'']' + ']><' + '/segment>''', '+') from @f where RowID = @current end
set @matchSql = @matchSql + iif(@current > 1, '-(e'+ @sCurrent + ')->a'+ @sCurrent, '')
if @current = @max begin set @whereSql = ' a'+ @sCurrent + '.AssetTypeID = ' + cast(@atID as nvarchar) + iif(@assetID is not null, ' and a'+ @sCurrent + '.ID = ' + cast(@assetID as nvarchar), '') + @whereSql
select @segmentSql = '(select L.L as ''@level'', L.A as ''@assetTypeId'', L.AssetID as ''@assetId'', L.Name as ''data()'' from ( '+@segmentSql+' ) L for xml path(''segment''), ELEMENTS, root(''path'')) as Segments' --select @segmentSql = '''<path>''+' + @segmentSql + '+''</path>'' as Segments' end
set @columnSql = iif(@current = @max, 'a'+ @sCurrent + '.ID as AssetID, ', '') + @columnSql + iif(@current = @max, ' as [Path]', '')
set @current = @current+1 end
set @columnSql = @columnSql + ', ' + @segmentSql
if @matchSql <> 'a1' begin set @matchSql = 'match(' + @matchSql+ ')' set @whereSql = ' and ' + @whereSql end else begin set @matchSql = '' end
set @sql = 'update T set T.[Path] = S.[Path], T.[Segments] = S.[Segments] ' + 'from graph.AssetNode T inner join (' + 'select ' + @columnSql + ' from ' + @fromSql + ' where ' + @matchSql + @whereSql + ') S on S.AssetID = T.ID' --print @sql execute sp_executesql @sql end end

